 'cos':lambda z:np.cos(z),'sin':lambda z:np.sin(z),'exp-':lambda z:np.exp(-z),'exp+':lambda z:np.exp(z),
 'log1p':lambda z:np.log(np.abs(1+z)),'tanh':lambda z:np.tanh(z),'inv1p':lambda z:1/(1+z**2)}
