known=lambda p: p[0]*v**2 + p[1]*np.log(np.abs(1+p[2]*x))*t + p[3]*np.exp(-p[4]*t**2)*v
def fit(fun,npar,starts=3):
    bb=None
    for s in range(starts):
        p0=np.r_[[-1,0.39,2.78,3.2,0.045],np.random.randn(npar)*0.5+1]
        try:
            with np.errstate(all='ignore'):
                rr=least_squares(lambda p: fun(p)-y,p0,max_nfev=200)
            if np.all(np.isfinite(rr.fun)) and (bb is None or rr.cost<bb.cost): bb=rr
        except Exception: pass
    return bb
