ins={'x':x,'t':t,'v':v}
# power product c * A^a * B^b
for (na,A),(nb,B) in [(('x',x),('t',t)),(('x',x),('v',v)),(('t',t),('v',v))]:
    fun=lambda p,A=A,B=B: known(p)+p[5]*np.abs(A)**p[6]*np.abs(B)**p[7]
